    public static JSONObject descriptor(){JSONObject o=new JSONObject();try{return o.put("id","run143_forgotten_secrets_character_options").put("source",SOURCE).put("source_sha256",SHA).put("patrons",PATRONS.length).put("invocations",INV.length).put("class_variants",2).put("familiar_dependencies",FAMILIARS.length).put("summon_dependencies",SUMMONS.length).put("expanded_spell_lists",PATRONS.length).put("custom_spells_deferred_block_b",false).put("custom_spells_runtime","Run149ForgottenSecretsSpellEngine").put("effect_pipeline_complete_for_block_a",true).put("effect_pipeline_complete_for_block_b",true).put("auto_rolls",false);}catch(Exception e){return o;}}
