    public static boolean isInvocation(String x){return invocationRow(x)!=null;}
    public static JSONObject lookupInvocation(String x){JSONObject o=new JSONObject();try{String[] r=invocationRow(x);if(r==null)return o.put("known",false);return o.put("known",true).put("invocation",r[1]).put("patron",r[0].equals("*")?"universal":r[0]).put("minimum_level",Integer.parseInt(r[2])).put("pact",r[3]).put("requires_eldritch_blast",Boolean.parseBoolean(r[4])).put("book",SOURCE).put("runtime","Run143ForgottenSecretsEngine").put("mechanics_compiled",true).put("auto_rolls",false);}catch(Exception e){return o;}}
