    public static JSONObject familiarStatblock(String name){JSONObject o=new JSONObject();try{for(String[] r:FAMILIARS)if(n(r[0]).equals(n(name))){o.put("known",true).put("name",r[0]).put("ac",Integer.parseInt(r[1])).put("hp",Integer.parseInt(r[2])).put("speed",r[3]).put("cr",r[4]).put("source",SOURCE).put("pact_chain_eligible",true).put("auto_rolls",false);applyFamiliarDetails(o,r[0]);return o;}for(String[] r:SUMMONS)if(n(r[0]).equals(n(name))){o.put("known",true).put("name",r[0]).put("ac",Integer.parseInt(r[1])).put("hp",Integer.parseInt(r[2])).put("speed",r[3]).put("cr",r[4]).put("source",SOURCE).put("pact_chain_eligible",false).put("auto_rolls",false);applyFamiliarDetails(o,r[0]);return o;}return o.put("known",false);}catch(Exception e){return o;}}

    public static JSONObject install(){JSONObject out=new JSONObject();JSONArray failed=new JSONArray();int ok=0,expected=PATRONS.length+INV.length+2+FAMILIARS.length+SUMMONS.length;try{
      for(String p:PATRONS)if(register("subclass",p,"patron rules pp. 4-35"))ok++;else failed.put(p);
      for(String[] r:INV)if(register("invocation",r[1],r[0].equals("*")?"Appendix A pp. 36-37":"patron invocation pp. 5-34"))ok++;else failed.put(r[1]);
      if(register("class_option",BARGAIN_ARCHIVIST,"Appendix A p. 36"))ok++;else failed.put(BARGAIN_ARCHIVIST);
      if(register("class_option",BARGAIN_PRIEST,"Appendix A p. 36"))ok++;else failed.put(BARGAIN_PRIEST);
      for(String[] r:FAMILIARS)if(register("familiar",r[0],"Appendix D pp. 44-51"))ok++;else failed.put(r[0]);
      for(String[] r:SUMMONS)if(register("summon",r[0],r[0].equals("Ink Lynx")?"Shadowcat pp. 25-26":"Wild Huntsman p. 35"))ok++;else failed.put(r[0]);
      return out.put("installed",ok).put("expected",expected).put("failed",failed).put("complete",ok==expected).put("auto_rolls",false);
    }catch(Exception e){try{return out.put("installed",ok).put("expected",expected).put("failed",failed).put("complete",false).put("error",e.getMessage());}catch(Exception ignored){return out;}}}
    private static boolean register(String kind,String name,String locator){try{String eid="run143."+kind+"."+n(name).replace(' ','_');JSONObject ev=new JSONObject().put("evidence_id",eid).put("content_kind",kind).put("content_name",name).put("source_book",SOURCE).put("source_locator",locator).put("source_sha256",SHA).put("revision",1);JSONObject er=AuthorizedMechanicalEvidenceRegistry.registerReviewed(ev);if(!er.optBoolean("registered",false))return false;JSONObject basis=new JSONObject(ev.toString()).put("source_type","reviewed_evidence");JSONObject mech=new JSONObject().put("effect_pipeline_complete",true).put("execution_status","compiled_effect_pipeline").put("runtime_resolver","Run143ForgottenSecretsEngine").put("auto_rolls",false).put("auto_mutation_allowed",false).put("custom_spells_deferred_block_b",false).put("custom_spells_runtime","Run149ForgottenSecretsSpellEngine");return CompiledContentMechanicsEngine.register(kind,name,mech,basis).optBoolean("registered",false);}catch(Exception e){return false;}}

