    public static boolean applyPatronMechanics(JSONObject s){String patron=patronOf(s);if(!isPatron(patron))return false;try{int lvl=level(s);s.put("subclass_name",canonicalPatron(patron)).put("subclass_runtime","Run143ForgottenSecretsEngine").put("subclass_source",SOURCE).put("subclass_mechanics_compiled",true).put("subclass_auto_rolls",false).put("run143_custom_spells_runtime","Run149ForgottenSecretsSpellEngine");JSONObject r=resources(s);s.put("run143_expanded_spell_list",expandedSpellList(canonicalPatron(patron))).put("run143_expanded_spells_custom_runtime","Run149ForgottenSecretsSpellEngine");applyPatronPassives(s,canonicalPatron(patron),lvl,r);applySelectedInvocationPassives(s,lvl);s.put("run143_resources",r);return true;}catch(Exception e){return false;}}

